const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/client\"\n}\n\n// ----------------------------------------------------\n// 1. OUTLETS & BRANDS (سول ميت كافيه & حلواني أبو عادل)\n// ----------------------------------------------------\nmodel Outlet {\n  id        String   @id @default(cuid())\n  name      String // \"سول ميت كافيه (Soulmate Cafe)\" | \"حلواني أبو عادل (Abu Adel Patisserie)\"\n  code      String   @unique // \"SOULMATE_CAFE\" | \"ABU_ADEL_PATISSERIE\"\n  type      String   @default(\"CAFE\") // \"CAFE\" | \"PASTRY_SHOP\"\n  address   String\n  phone     String\n  whatsapp  String?\n  logoUrl   String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  users                User[]\n  tables               DiningTable[]\n  menuItems            MenuItem[]\n  rawMaterials         RawMaterial[]\n  orders               Order[]\n  shifts               Shift[]\n  expenses             Expense[]\n  reservations         Reservation[]\n  chatMessages         ChatMessage[]\n  inventoryAudits      InventoryAudit[]\n  pastryAudits         PastryAudit[]\n  dailyCloses          DailyClose[]\n  deliveryDrivers      DeliveryDriver[]\n  factoryOrders        FactoryOrder[]\n  suppliers            Supplier[]\n  supplierTransactions SupplierTransaction[]\n}\n\n// ----------------------------------------------------\n// 2. USERS, ROLES & PERMISSIONS (المستخدمين وطاقم العمل)\n// ----------------------------------------------------\nmodel User {\n  id           String   @id @default(cuid())\n  name         String\n  username     String   @unique\n  passwordHash String\n  pin          String   @default(\"159920\") // PIN code for quick cashier / POS switches\n  phone        String?\n  role         String   @default(\"cashier\") // owner, general_manager, branch_manager, cashier, barista, chef, waiter\n  outletId     String?\n  outlet       Outlet?  @relation(fields: [outletId], references: [id], onDelete: SetNull)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 3. DINING TABLES & ZONES (ترابيزات كافيه سول ميت)\n// ----------------------------------------------------\nmodel DiningTable {\n  id            String   @id @default(cuid())\n  outletId      String\n  outlet        Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  tableNumber   String // \"T-01\", \"T-02\", \"VIP-1\", \"TERRACE-2\"\n  zone          String   @default(\"INDOOR\") // \"INDOOR\", \"OUTDOOR\", \"VIP_LOUNGE\"\n  capacity      Int      @default(4)\n  status        String   @default(\"AVAILABLE\") // \"AVAILABLE\", \"OCCUPIED\", \"BILL_REQUESTED\", \"RESERVED\"\n  activeOrderId String?\n  qrCodeUrl     String?\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 4. MENU ITEMS & FINISHED GOODS (أصناف الكافيه وحلواني أبو عادل)\n// ----------------------------------------------------\nmodel MenuItem {\n  id                    String   @id @default(cuid())\n  outletId              String\n  outlet                Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  nameAr                String\n  nameEn                String?\n  category              String // HOT_COFFEE, COLD_COFFEE, BEVERAGES, WAFFLES_PANCAKES, ORIENTAL_SWEETS, WESTERN_PASTRY, CAKES_TORTES, ICE_CREAM, GIFT_BOXES\n  price                 Float\n  costPrice             Float    @default(0) // Calculated from Recipe or purchase cost\n  durationMinutes       Int      @default(5)\n  description           String?\n  image                 String?\n  itemType              String   @default(\"PREPARED_BEVERAGE\") // \"PREPARED_BEVERAGE\" (uses recipe) | \"READY_PASTRY\" (finished unit) | \"RETAIL\"\n  unitType              String   @default(\"PIECE\") // \"PIECE\", \"PORTION\", \"KG\", \"BOX\"\n  openingStock          Float    @default(0) // رصيد بداية المدة الافتتاحي للحلويات\n  stockQty              Float    @default(0) // الرصيد الفعلي الحالي بالمحل (يدعم الكسور للكيلو)\n  minStockAlert         Float    @default(10)\n  defaultSupplierId     String?\n  isAvailable           Boolean  @default(true)\n  sortOrder             Int      @default(0)\n  loyaltyPointsEarned   Int      @default(5)\n  loyaltyPointsRequired Int      @default(50)\n  createdAt             DateTime @default(now())\n\n  recipes   RecipeItem[]\n  movements ProductMovement[]\n}\n\n// ----------------------------------------------------\n// 4.1 PRODUCT MOVEMENTS (حركات توريد ومبيعات وجرد حلويات أبو عادل)\n// ----------------------------------------------------\nmodel ProductMovement {\n  id            String   @id @default(cuid())\n  menuItemId    String\n  menuItem      MenuItem @relation(fields: [menuItemId], references: [id], onDelete: Cascade)\n  type          String // \"INBOUND\" (توريد من المعمل), \"SALE\" (بيع فاتورة), \"ADJUSTMENT\" (تسوية جردية), \"INITIAL\" (رصيد بداية المدة)\n  quantity      Float // positive for inbound/surplus, negative for sale/deficit\n  unitCost      Float? // Cost price\n  totalCost     Float? // quantity * unitCost\n  supplierName  String? // اسم الشيف أو المعمل\n  invoiceNumber String? // رقم إذن التشغيل أو الفاتورة\n  orderNumber   String? // رقم الفاتورة أو الأوردر\n  recordedBy    String? // اسم المستخدم\n  notes         String? // ملاحظات\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 4.2 PASTRY AUDITS (محاضر الجرد المقارن لحلويات أبو عادل)\n// ----------------------------------------------------\nmodel PastryAudit {\n  id          String            @id @default(cuid())\n  outletId    String\n  outlet      Outlet            @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  auditorName String            @default(\"المايسترو\")\n  notes       String?\n  items       PastryAuditItem[]\n  createdAt   DateTime          @default(now())\n}\n\nmodel PastryAuditItem {\n  id            String      @id @default(cuid())\n  auditId       String\n  audit         PastryAudit @relation(fields: [auditId], references: [id], onDelete: Cascade)\n  menuItemId    String\n  menuItemName  String\n  unitType      String\n  price         Float       @default(0)\n  costPrice     Float       @default(0)\n  openingStock  Float       @default(0)\n  totalInbound  Float       @default(0)\n  totalSold     Float       @default(0)\n  expectedStock Float       @default(0)\n  actualStock   Float       @default(0)\n  variance      Float       @default(0)\n  varianceCost  Float       @default(0)\n  status        String      @default(\"MATCH\") // \"MATCH\" | \"DEFICIT\" | \"SURPLUS\"\n  createdAt     DateTime    @default(now())\n}\n\n// ----------------------------------------------------\n// 5. RAW MATERIALS INVENTORY (خامات البار ومخزن المشروبات)\n// ----------------------------------------------------\nmodel RawMaterial {\n  id                String   @id @default(cuid())\n  outletId          String\n  outlet            Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  nameAr            String // بن إسبريسو حبوب، حليب كامل الدسم، سيرب فانيليا، صوص لوتس، أكواب ورقية\n  unit              String   @default(\"GRAM\") // \"GRAM\", \"ML\", \"PIECE\", \"PUMP\", \"KG\", \"LITER\"\n  openingStock      Float    @default(0) // رصيد بداية المدة\n  currentStock      Float    @default(1000)\n  minStockAlert     Float    @default(200)\n  leadTimeDays      Int      @default(3) // مهلة تنفيذ المصنع / التوريد بالأيام (مثلاً 21 يوم للأكواب الكرتون)\n  avgDailyUsage     Float    @default(0) // الاستهلاك اليومي التقديري اليدوي (اختياري)\n  costPerUnit       Float    @default(0.5) // EGP per Gram or ML\n  supplierName      String?\n  defaultSupplierId String?\n  notes             String?\n  updatedAt         DateTime @default(now()) @updatedAt\n\n  recipeUsage RecipeItem[]\n  movements   RawMaterialMovement[]\n}\n\n// ----------------------------------------------------\n// 5.1 RAW MATERIAL MOVEMENTS (حركات توريد واستهلاك وتسوية الخامات)\n// ----------------------------------------------------\nmodel RawMaterialMovement {\n  id            String      @id @default(cuid())\n  rawMaterialId String\n  rawMaterial   RawMaterial @relation(fields: [rawMaterialId], references: [id], onDelete: Cascade)\n  type          String // \"INBOUND\" (توريد بضاعة), \"CONSUMPTION\" (استهلاك ريسيبي مبيعات), \"ADJUSTMENT\" (تسوية جردية)\n  quantity      Float // Quantity in rawMaterial.unit (positive for inbound/surplus, negative for consumption/deficit)\n  costPerUnit   Float? // Cost per unit at time of movement\n  totalCost     Float? // Total monetary value\n  supplierName  String? // اسم المورد\n  invoiceNumber String? // رقم الفاتورة أو إذن التوريد\n  orderNumber   String? // رقم الطلب لو استهلاك ريسيبي\n  recordedBy    String? // اسم المسؤول\n  notes         String? // ملاحظات الحركة\n  createdAt     DateTime    @default(now())\n}\n\n// ----------------------------------------------------\n// 5.2 INVENTORY RECONCILIATION AUDITS (محاضر الجرد المقارن الفوري)\n// ----------------------------------------------------\nmodel InventoryAudit {\n  id          String               @id @default(cuid())\n  outletId    String\n  outlet      Outlet               @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  auditorName String               @default(\"المايسترو\")\n  notes       String?\n  items       InventoryAuditItem[]\n  createdAt   DateTime             @default(now())\n}\n\nmodel InventoryAuditItem {\n  id              String         @id @default(cuid())\n  auditId         String\n  audit           InventoryAudit @relation(fields: [auditId], references: [id], onDelete: Cascade)\n  rawMaterialId   String\n  rawMaterialName String\n  unit            String\n  costPerUnit     Float          @default(0)\n  openingStock    Float          @default(0)\n  totalInbound    Float          @default(0)\n  totalConsumed   Float          @default(0)\n  expectedStock   Float          @default(0)\n  actualStock     Float          @default(0)\n  variance        Float          @default(0) // actual - expected\n  varianceCost    Float          @default(0) // variance * costPerUnit\n  status          String         @default(\"MATCH\") // \"MATCH\" | \"DEFICIT\" | \"SURPLUS\"\n  createdAt       DateTime       @default(now())\n}\n\n// ----------------------------------------------------\n// 6. RECIPES & BILL OF MATERIALS (الريسيبي وخصم الخامات)\n// ----------------------------------------------------\nmodel RecipeItem {\n  id            String      @id @default(cuid())\n  menuItemId    String\n  menuItem      MenuItem    @relation(fields: [menuItemId], references: [id], onDelete: Cascade)\n  rawMaterialId String\n  rawMaterial   RawMaterial @relation(fields: [rawMaterialId], references: [id], onDelete: Cascade)\n  qtyRequired   Float // 18 grams, 160 ml, 1 piece\n  createdAt     DateTime    @default(now())\n\n  @@unique([menuItemId, rawMaterialId])\n}\n\n// ----------------------------------------------------\n// 7. CUSTOMERS & LOYALTY CRM (قاعدة العملاء وبرنامج الولاء)\n// ----------------------------------------------------\nmodel Customer {\n  id               String    @id @default(cuid())\n  name             String\n  phone            String    @unique\n  email            String?\n  passwordHash     String?\n  isVerified       Boolean   @default(false)\n  verificationCode String?\n  address          String?\n  city             String?\n  loyaltyPoints    Int       @default(0)\n  totalSpent       Float     @default(0)\n  visitCount       Int       @default(0)\n  lastVisitAt      DateTime?\n  notes            String?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @default(now()) @updatedAt\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 7.5 DELIVERY ZONES & DYNAMIC SHIPPING FEES (مناطق التوصيل الديناميكية)\n// ----------------------------------------------------\nmodel DeliveryZone {\n  id            String   @id @default(cuid())\n  nameAr        String // حدائق القبة، مصر الجديدة، مدينة نصر...\n  nameEn        String?\n  fee           Float    @default(20)\n  estimatedTime String   @default(\"30-45 دقيقة\")\n  isActive      Boolean  @default(true)\n  sortOrder     Int      @default(0)\n  createdAt     DateTime @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 7.6 DELIVERY DRIVERS (عمال التوصيل / الطيارين)\n// ----------------------------------------------------\nmodel DeliveryDriver {\n  id          String   @id @default(cuid())\n  outletId    String?\n  outlet      Outlet?  @relation(fields: [outletId], references: [id], onDelete: SetNull)\n  name        String\n  phone       String\n  vehicleInfo String?\n  notes       String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 8. ORDERS & TICKETS (الطلبات والشيكات والفواتير)\n// ----------------------------------------------------\nmodel Order {\n  id                String          @id @default(cuid())\n  outletId          String\n  outlet            Outlet          @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  orderNumber       String          @unique // \"SOUL-1001\" or \"ADEL-1001\"\n  orderType         String          @default(\"DINE_IN\") // \"DINE_IN\", \"TAKEAWAY\", \"DELIVERY\"\n  tableId           String?\n  table             DiningTable?    @relation(fields: [tableId], references: [id], onDelete: SetNull)\n  tableNumber       String?\n  deliveryZoneId    String?\n  deliveryZone      DeliveryZone?   @relation(fields: [deliveryZoneId], references: [id], onDelete: SetNull)\n  deliveryZoneName  String? // Snapshot of area/zone name\n  deliveryAddress   String?\n  deliveryPhone     String?\n  deliveryNotes     String?\n  driverId          String?\n  driver            DeliveryDriver? @relation(fields: [driverId], references: [id], onDelete: SetNull)\n  driverName        String? // اسم الطيار المخصص للتوصيل\n  driverPhone       String? // رقم تليفون الطيار\n  dispatchedAt      DateTime? // وقت خروج الأوردر مع الطيار\n  isScheduled       Boolean         @default(false) // طلب مسبق / حجز لموعد محدد\n  scheduledFor      DateTime? // تاريخ ووقت التسليم المطلوب\n  depositRequired   Float           @default(0)\n  depositPaid       Float           @default(0)\n  depositStatus     String          @default(\"NONE\") // \"NONE\", \"PENDING_VERIFICATION\", \"CONFIRMED\"\n  depositReceiptUrl String?\n  alertSent48h      Boolean         @default(false)\n  alertSent24h      Boolean         @default(false)\n  status            String          @default(\"NEW_PENDING\") // \"NEW_PENDING\", \"PREPARING\", \"READY_TO_SERVE\", \"OUT_FOR_DELIVERY\", \"COMPLETED\", \"CANCELLED\"\n  paymentStatus     String          @default(\"PENDING\") // \"PENDING\", \"PAID\"\n  paymentMethod     String          @default(\"CASH\") // \"CASH\", \"CARD\", \"INSTAPAY\", \"VODAFONE_CASH\", \"SPLIT\"\n\n  subtotal          Float @default(0)\n  serviceCharge     Float @default(0)\n  taxAmount         Float @default(0)\n  deliveryFee       Float @default(0)\n  discountAmount    Float @default(0)\n  tipAmount         Float @default(0)\n  finalAmount       Float @default(0)\n  commissionPercent Float @default(0)\n  commissionAmount  Float @default(0)\n  platformNetAmount Float @default(0)\n\n  cashierName   String?\n  waiterName    String?\n  customerName  String?\n  customerPhone String?\n  customerId    String?\n  customer      Customer? @relation(fields: [customerId], references: [id], onDelete: SetNull)\n\n  pointsEarned   Int     @default(0)\n  pointsRedeemed Int     @default(0)\n  notes          String?\n  items          String // JSON Array of ordered items [{ menuItemId, nameAr, price, qty, notes, itemType }]\n\n  isEdited        Boolean   @default(false) // تم تعديل أصناف/كميات الفاتورة (\"فاتورة معدلة\")\n  revisionCount   Int       @default(0)\n  paymentModified Boolean   @default(false) // تم تغيير طريقة الدفع (\"تعديل دفع\")\n  lastEditReason  String?\n  lastEditedBy    String?\n  lastEditedAt    DateTime?\n\n  createdAt DateTime  @default(now())\n  settledAt DateTime?\n\n  kdsTickets KdsTicket[]\n  auditLogs  OrderAuditLog[]\n}\n\n// ----------------------------------------------------\n// 9. KDS (KITCHEN & BARISTA DISPLAY SYSTEM - شاشة المطبخ والبار)\n// ----------------------------------------------------\nmodel KdsTicket {\n  id           String    @id @default(cuid())\n  orderId      String\n  order        Order     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  station      String    @default(\"BARISTA\") // \"BARISTA\", \"KITCHEN\", \"PASTRY_COUNTER\"\n  itemsSummary String // JSON or formatted string of items for this station\n  status       String    @default(\"QUEUED\") // \"QUEUED\", \"IN_PREPARATION\", \"DONE\"\n  createdAt    DateTime  @default(now())\n  completedAt  DateTime?\n}\n\n// ----------------------------------------------------\n// 10. SHIFTS & CASH REGISTER (الورديات والخزنة وتقفيل الدرج)\n// ----------------------------------------------------\nmodel Shift {\n  id               String  @id @default(cuid())\n  outletId         String\n  outlet           Outlet  @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  shiftNumber      Int     @default(1)\n  openedBy         String // Cashier name\n  closedBy         String?\n  openingCashFloat Float   @default(0) // فكة الدرج الافتتاحية\n  expectedCash     Float   @default(0)\n  actualCash       Float   @default(0)\n  difference       Float   @default(0) // Actual - Expected\n\n  cashCollected     Float @default(0)\n  visaCollected     Float @default(0)\n  instapayCollected Float @default(0)\n  vodafoneCollected Float @default(0)\n  talabatCollected  Float @default(0)\n  talabatCommission Float @default(0)\n  deliveryFeesTotal Float @default(0) // رسوم الدليفري المنفصلة (مستحقات الطيارين)\n  totalRevenue      Float @default(0) // صافي إيراد المحل بدون رسوم التوصيل\n  expensesTotal     Float @default(0)\n  ticketsCount      Int   @default(0)\n\n  handedTo String? // المالك أو مدير الفرع المستلم\n  notes    String?\n  status   String    @default(\"OPEN\") // \"OPEN\", \"CLOSED\"\n  openedAt DateTime  @default(now())\n  closedAt DateTime?\n}\n\n// ----------------------------------------------------\n// 10.1 DAILY CLOSE (إقفال اليومية الشاملة لكافة الشيفتات)\n// ----------------------------------------------------\nmodel DailyClose {\n  id                     String   @id @default(cuid())\n  outletId               String\n  outlet                 Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  closeDate              DateTime @default(now())\n  dayName                String? // \"الأحد\", \"الإثنين\", إلخ\n  shiftsCount            Int      @default(2)\n  totalRevenue           Float    @default(0)\n  totalCash              Float    @default(0)\n  totalVisa              Float    @default(0)\n  totalInstapay          Float    @default(0)\n  totalVodafone          Float    @default(0)\n  totalTalabat           Float    @default(0)\n  totalTalabatCommission Float    @default(0)\n  totalExpenses          Float    @default(0)\n  netCashInSafe          Float    @default(0)\n  ordersCount            Int      @default(0)\n  closedBy               String\n  notes                  String?\n  createdAt              DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 11. EXPENSES & PETTY CASH (المصروفات والنثريات اليومية)\n// ----------------------------------------------------\nmodel Expense {\n  id         String   @id @default(cuid())\n  outletId   String\n  outlet     Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  title      String\n  amount     Float\n  category   String   @default(\"SUPPLIES\") // \"RAW_MATERIALS\", \"SUPPLIES\", \"MAINTENANCE\", \"SALARIES\", \"UTILITIES\", \"MISC\"\n  recordedBy String\n  notes      String?\n  createdAt  DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 12. SYSTEM SETTINGS & LOYALTY TOGGLE (الإعدادات العامة والولاء)\n// ----------------------------------------------------\nmodel SystemSettings {\n  id            String @id @default(\"default-settings\")\n  brandNameAr   String @default(\"مجموعة أبو عادل وسول ميت كافيه (حلواني & كافيه عصري)\")\n  brandNameEn   String @default(\"ABU ADEL PATISSERIE & SOULMATE CAFE\")\n  soulmatePhone String @default(\"01099887766\")\n  abuAdelPhone  String @default(\"15992\")\n  hotline       String @default(\"15992\")\n  whatsapp      String @default(\"01099887766\")\n  haliyomakUrl  String @default(\"https://haliyomak.com/\")\n  facebookUrl   String @default(\"https://www.facebook.com/hashtag/soulmate_cafe\")\n\n  serviceChargePercent   Float   @default(12.0)\n  taxPercent             Float   @default(14.0)\n  deliveryFee            Float   @default(20.0) // مصاريف الدليفري الثابتة\n  preOrderDepositPercent Float   @default(30.0) // نسبة العربون الافتراضية للحجوزات المسبقة %\n  instapayAccount        String? // حساب إنستاباي للتحويلات والعربون\n  vodafoneCashNumber     String? // رقم فودافون كاش للتحويلات والعربون\n  isServiceChargeEnabled Boolean @default(false)\n  isTaxEnabled           Boolean @default(false)\n\n  // 👑 برنامج الولاء والهدايا (يطبق على أبو عادل وسول ميت ديناميكياً)\n  isLoyaltyEnabled         Boolean @default(true)\n  pointsPerPoundSpent      Float   @default(1.0) // مثال: 1 نقطة لكل 1 جنيه إنفاق\n  poundValuePerPoint       Float   @default(0.1) // قيمة الاستبدال المباشر لكل نقطة (اختياري)\n  loyaltyRewardThreshold   Int     @default(3000) // الهدف المطلوب (مثال: 3000 نقطة / جنيه)\n  loyaltyRewardValue       Float   @default(200) // قيمة الهدية عند الوصول للهدف (مثال: 200 جنيه)\n  loyaltyAppliesToAbuAdel  Boolean @default(true)\n  loyaltyAppliesToSoulmate Boolean @default(true)\n  loyaltyMotivationalMsg   String  @default(\"جمع نقط مع كل أوردر من حلواني أبو عادل وسول ميت كافيه — وكل ما توصل للهدف هتاخد هدية فورية تختار بيها أي حاجة تحبها! 🎁✨\")\n\n  // 🎁 إدارة العروض الخاصة وماكينة الخصومات في اللاندينج بيدج\n  offersEnabled Boolean @default(true)\n  specialOffers String?\n\n  // 🔔 التقرير اليومي التلقائي والتنبيه الصوتي + توريد أبو عادل -> سول ميت + Gemini\n  dailyReportAlertEnabled     Boolean @default(true)\n  dailyReportAlertTime        String  @default(\"20:00\") // 8:00 مساءً بتوقيت القاهرة (قابل للتعديل)\n  dailyReportRepeatSeconds    Int     @default(4)\n  dailyReportAlertSound       Boolean @default(true)\n  internalSupplyMarkupEnabled Boolean @default(false) // تفعيل هامش بسيط عند توريد أبو عادل لسول ميت\n  internalSupplyMarkupPercent Float   @default(0.0) // النسبة المئوية للهامش الإضافي (الافتراضي 0% نفس التكلفة)\n  talabatCommissionPercent    Float   @default(25.0) // عمولة طلبات (Talabat) الافتراضية %\n  geminiApiKey                String? // اختياري كاحتياطي في السحابة\n\n  receiptFooterNotes String   @default(\"شكراً لزيارتكم حلواني أبو عادل وسول ميت كافيه • حلي يومك واستمتع بقهوتك ☕🍰\")\n  systemLocked       Boolean  @default(false)\n  lockMessage        String   @default(\"النظام مغلق مؤقتاً لأعمال الجرد والصيانة الدورية.\")\n  vapidPublicKey     String?\n  vapidPrivateKey    String?\n  updatedAt          DateTime @default(now()) @updatedAt\n}\n\n// ----------------------------------------------------\n// 13. RESERVATIONS & EVENT BOOKINGS (حجز الترابيزات والحفلات)\n// ----------------------------------------------------\nmodel Reservation {\n  id              String   @id @default(cuid())\n  outletId        String\n  outlet          Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  customerName    String\n  customerPhone   String\n  customerEmail   String?\n  reservationType String   @default(\"TABLE\") // \"TABLE\" (ترابيزة عادية) | \"PARTY\" (حفلة / عيد ميلاد / مناسبة)\n  guestCount      Int      @default(2)\n  bookingDate     DateTime\n  timeSlot        String // \"07:00 PM\"\n  zonePreference  String? // \"INDOOR\", \"OUTDOOR_TERRACE\", \"VIP_LOUNGE\"\n  specialRequests String?\n  status          String   @default(\"PENDING\") // \"PENDING\", \"CONFIRMED\", \"CANCELLED\", \"COMPLETED\"\n  createdAt       DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 14. INTERNAL LIVE CHAT (الشات الداخلي بين الزبون والباريستا/الإدارة)\n// ----------------------------------------------------\nmodel ChatMessage {\n  id          String   @id @default(cuid())\n  outletId    String\n  outlet      Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  senderType  String // \"CUSTOMER\" | \"STAFF\"\n  senderName  String\n  senderPhone String?\n  tableNumber String?\n  orderNumber String?\n  message     String\n  imageUrl    String?\n  isRead      Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 15. DAILY FACTORY PROCUREMENT ORDERS (طلبيات المصنع اليومية لأبو عادل)\n// ----------------------------------------------------\nmodel FactoryOrder {\n  id         String             @id @default(cuid())\n  outletId   String\n  outlet     Outlet             @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  targetDate DateTime\n  status     String             @default(\"DRAFT\") // \"DRAFT\", \"SENT_TO_FACTORY\", \"RECEIVED\"\n  createdBy  String             @default(\"المايسترو\")\n  notes      String?\n  items      FactoryOrderItem[]\n  createdAt  DateTime           @default(now())\n  updatedAt  DateTime           @default(now()) @updatedAt\n}\n\nmodel FactoryOrderItem {\n  id             String       @id @default(cuid())\n  factoryOrderId String\n  factoryOrder   FactoryOrder @relation(fields: [factoryOrderId], references: [id], onDelete: Cascade)\n  menuItemId     String\n  menuItemName   String\n  unitType       String\n  currentStock   Float        @default(0)\n  minStockLevel  Float        @default(0)\n  shortageQty    Float        @default(0)\n  preOrderQty    Float        @default(0)\n  suggestedQty   Float        @default(0)\n  approvedQty    Float        @default(0)\n  notes          String?\n}\n\n// ----------------------------------------------------\n// 16. SUPPLIERS & INTER-BRAND LEDGER (المصنع والموردين وحساب أبو عادل <-> سول ميت)\n// ----------------------------------------------------\nmodel Supplier {\n  id                     String   @id @default(cuid())\n  outletId               String\n  outlet                 Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  code                   String? // \"MAIN_FACTORY\", \"ABU_ADEL_INTERNAL\", \"CUPS_PACKAGING\", custom\n  name                   String\n  supplierType           String   @default(\"FACTORY\") // \"FACTORY\" | \"RAW_MATERIALS\" | \"INTERNAL_ABU_ADEL\" | \"GENERAL\"\n  phone                  String?\n  contactPerson          String?\n  address                String?\n  openingBalance         Float    @default(0) // رصيد أول المدة الدائن للمورد (علينا له)\n  isInternalSupply       Boolean  @default(false) // true لحساب توريد حلواني أبو عادل -> سول ميت كافيه\n  deductFromSourceOutlet Boolean  @default(true) // عند توريد أبو عادل لسول ميت: خصم من مخزن أبو عادل تلقائياً\n  notes                  String?\n  isActive               Boolean  @default(true)\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @default(now()) @updatedAt\n\n  transactions SupplierTransaction[]\n}\n\nmodel SupplierTransaction {\n  id              String   @id @default(cuid())\n  supplierId      String\n  supplier        Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  outletId        String\n  outlet          Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  type            String // \"INVOICE\" | \"PAYMENT\" | \"RETURN\" | \"ADJUSTMENT\"\n  invoiceNumber   String?\n  transactionDate DateTime @default(now())\n  totalAmount     Float    @default(0) // إجمالي قيمة الفاتورة أو مبلغ السداد\n  paidAmount      Float    @default(0) // المدفوع الفوري وقت الفاتورة (إن وجد)\n  remainingAmount Float    @default(0) // الآجل المتبقي من الفاتورة وقت صدورها\n  paymentStatus   String   @default(\"CREDIT\") // \"PAID\" | \"PARTIAL\" | \"CREDIT\"\n  paymentMethod   String? // \"CASH\" | \"INSTAPAY\" | \"VODAFONE_CASH\" | \"BANK_TRANSFER\" | \"CARD\" | \"CREDIT\"\n  paymentSource   String   @default(\"OWNER_CURRENT_ACCOUNT\") // \"DRAWER\" | \"OWNER_CURRENT_ACCOUNT\" | \"MAIN_SAFE\" | \"BANK_ACCOUNT\"\n  expenseId       String? // رابط مصروف الدرج إذا سُدد نقدياً من درج الكاشير\n  itemsJson       String? // JSON: أصناف الفاتورة المهضومة بالذكاء الاصطناعي أو اليدوية\n  imageUrl        String? // رابط/أرشيف صورة الفاتورة\n  aiConfidence    String? // \"HIGH\" | \"MEDIUM\" | \"LOW\" | \"MANUAL\"\n  recordedBy      String   @default(\"المايسترو\")\n  notes           String?\n  createdAt       DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 17. ORDER AUDIT LOGS & ADMIN SECURITY ALERTS (سجل تعديل الفواتير والدفع وتنبيهات الإدارة)\n// ----------------------------------------------------\nmodel OrderAuditLog {\n  id               String   @id @default(cuid())\n  orderId          String\n  order            Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderNumber      String\n  outletId         String\n  outletName       String\n  actionType       String // \"INVOICE_EDIT\" | \"PAYMENT_EDIT\"\n  performedBy      String   @default(\"كاشير الفرع\")\n  reason           String\n  oldPaymentMethod String?\n  newPaymentMethod String?\n  oldFinalAmount   Float    @default(0)\n  newFinalAmount   Float    @default(0)\n  amountDiff       Float    @default(0)\n  oldItemsJson     String?\n  newItemsJson     String?\n  createdAt        DateTime @default(now())\n}\n\nmodel AdminNotification {\n  id           String    @id @default(cuid())\n  outletId     String?\n  orderId      String?\n  orderNumber  String?\n  category     String    @default(\"INVOICE_EDITED\") // \"INVOICE_EDITED\" | \"PAYMENT_EDITED\" | \"GENERAL\"\n  severity     String    @default(\"HIGH\")\n  title        String\n  message      String\n  actorName    String?\n  metadataJson String?\n  isRead       Boolean   @default(false)\n  readBy       String?\n  readAt       DateTime?\n  createdAt    DateTime  @default(now())\n}\n\nmodel PushSubscription {\n  id             String    @id @default(cuid())\n  endpoint       String    @unique\n  p256dh         String\n  auth           String\n  role           String    @default(\"CUSTOMER\") // OWNER, ADMIN, POS, KDS, CUSTOMER\n  outletId       String?\n  userId         String?\n  userName       String?\n  customerPhone  String?\n  userAgent      String?\n  isActive       Boolean   @default(true)\n  lastNotifiedAt DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n}\n\n// ----------------------------------------------------\n// 18. CONSIGNMENT RETURNS (أمانات البيع بين سول ميت وأبو عادل بالتكلفة)\n// ----------------------------------------------------\nmodel ConsignmentBatch {\n  id                 String   @id @default(cuid())\n  outletSourceCode   String   @default(\"SOULMATE_CAFE\")\n  outletDestCode     String   @default(\"ABU_ADEL_PATISSERIE\")\n  soulmateMenuItemId String\n  abuAdelMenuItemId  String?\n  itemName           String\n  unitType           String   @default(\"PIECE\")\n  unitCost           Float    @default(0)\n  sellingPrice       Float    @default(0)\n  sentQty            Float    @default(0)\n  soldQty            Float    @default(0)\n  returnedQty        Float    @default(0)\n  remainingQty       Float    @default(0)\n  soldRevenue        Float    @default(0)\n  settledAmount      Float    @default(0)\n  settlementMode     String   @default(\"PENDING\") // \"PENDING\" | \"OFFSET_DEBT\" | \"CASH_PAYOUT\"\n  status             String   @default(\"OPEN\") // \"OPEN\" | \"PARTIAL\" | \"SETTLED\"\n  notes              String?\n  recordedBy         String   @default(\"المايسترو\")\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @default(now()) @updatedAt\n}\n"
}

